 1	// @vitest-environment jsdom
 2	
 3	/**
 4	 * Tests for the "Orchestrator Runs" section of views/project-detail.js.
 5	 *
 6	 * Uses jsdom + vm.runInThisContext to load the browser-side scripts, then
 7	 * stubs globalThis.API and globalThis.marked to exercise the
 8	 * renderProjectDetail paths related to orchestrator run logs.
 9	 */
10	
11	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
12	import { readFileSync } from 'node:fs';
13	import { join } from 'node:path';
14	import vm from 'node:vm';
15	
16	// ---------------------------------------------------------------------------
17	// Load client scripts
18	// ---------------------------------------------------------------------------
19	
20	const publicDir = join(__dirname, '../../gui/public');
21	const utilsJs         = readFileSync(join(publicDir, 'utils.js'),                   'utf-8');
22	const projectDetailJs = readFileSync(join(publicDir, 'views/project-detail.js'),    'utf-8');
23	
24	beforeAll(() => {
25	  // Install stub globals needed by project-detail.js before it is evaluated
26	  (globalThis as Record<string, unknown>)['marked'] = {
27	    parse: (s: string) => '<p>' + s + '</p>',
28	  };
29	
30	  // OrchestratorWidgets stub — used by the queue-aware active run section (WP-013).
31	  (globalThis as Record<string, unknown>)['OrchestratorWidgets'] = {
32	    renderStatusCard:    vi.fn().mockReturnValue('<div class="orchestrator-status-card">card</div>'),
33	    renderKillButton:    vi.fn().mockImplementation((_id: string, _cb: () => void) => {
34	      const btn = document.createElement('button');
35	      btn.className = 'kill-btn';
36	      btn.textContent = 'Kill';
37	      return btn;
38	    }),
39	    renderDismissButton: vi.fn(),
40	    renderLogPreview:    vi.fn().mockReturnValue(vi.fn()), // returns a cleanup stub
41	    renderProgressBadge: vi.fn().mockReturnValue(''),
42	    renderCliReference:  vi.fn().mockReturnValue(''),
43	  };
44	
45	  // Router stub — used by Router._setPolling() in the active run section.
46	  (globalThis as Record<string, unknown>)['Router'] = {
47	    _setPolling:   vi.fn(),
48	    _clearPolling: vi.fn(),
49	  };
50	
51	  vm.runInThisContext(utilsJs);
52	  vm.runInThisContext(projectDetailJs);
53	});
54	
55	// Reset OrchestratorWidgets and Router mocks between tests.
56	beforeEach(() => {
57	  globalThis.OrchestratorWidgets.renderStatusCard
58	    .mockReturnValue('<div class="orchestrator-status-card">card</div>');
59	  globalThis.OrchestratorWidgets.renderKillButton
60	    .mockImplementation((_id: string, _cb: () => void) => {
61	      const btn = document.createElement('button');
62	      btn.className = 'kill-btn';
63	      btn.textContent = 'Kill';
64	      return btn;
65	    });
66	  globalThis.OrchestratorWidgets.renderLogPreview.mockReturnValue(vi.fn());
67	  vi.clearAllMocks();
68	});
69	
70	// ---------------------------------------------------------------------------
71	// Global type declarations
72	// ---------------------------------------------------------------------------
73	
74	declare global {
75	  // eslint-disable-next-line no-var
76	  var renderProjectDetail: (app: HTMLElement, slug: string) => void;
77	  // eslint-disable-next-line no-var
78	  var API: Record<string, (...args: unknown[]) => Promise<unknown>>;
79	  // eslint-disable-next-line no-var
80	  var marked: { parse: (s: string) => string };
81	  // eslint-disable-next-line no-var
82	  var OrchestratorWidgets: {
83	    renderStatusCard:    Mock;
84	    renderKillButton:    Mock;
85	    renderDismissButton: Mock;
86	    renderLogPreview:    Mock;
87	    renderProgressBadge: Mock;
88	    renderCliReference:  Mock;
89	  };
90	  // eslint-disable-next-line no-var
91	  var Router: {
92	    _setPolling:   Mock;
93	    _clearPolling: Mock;
94	  };
95	}
96	
97	// ---------------------------------------------------------------------------
98	// Helpers
99	// ---------------------------------------------------------------------------

 98	// Helpers
 99	// ---------------------------------------------------------------------------
100	
101	/** Minimal valid project response from API.getProject */
102	function makeProject(overrides: Record<string, unknown> = {}) {
103	  return {
104	    meta: {
105	      status: 'IN_PROGRESS',
106	      runner: overrides.runner as string | undefined,
107	      title: 'Test Project',
108	      plan_path: '/some/path',
109	      date_created: '2026-01-01T00:00:00Z',
110	      last_updated: '2026-01-01T00:00:00Z',
111	      ...overrides,
112	    },
113	    work_packages: [],
114	    project_comments: [],
115	    project_name: 'Test Project',
116	    timing: null,
117	    server_version: null,
118	    ledger_version: null,
119	    synthesis_generated: false,
120	  };
121	}
122	
123	/**
124	 * Installs a globalThis.API stub and calls renderProjectDetail.
125	 * Returns a promise that resolves once the initial synchronous render
126	 * AND any microtasks (promise resolutions) have settled.
127	 */
128	async function renderWithAPI(
129	  app: HTMLElement,
130	  slug: string,
131	  apiStubs: {
132	    getProject?: () => Promise<unknown>;
133	    getPlanDocument?: () => Promise<unknown>;
134	    getWorkPackageOverview?: () => Promise<unknown>;
135	    getProjectHealth?: () => Promise<unknown>;
136	    getRunLogs?: () => Promise<unknown>;
137	    orchestratorGetQueue?: () => Promise<unknown>;
138	    getRunMetadata?: () => Promise<unknown>;
139	    orchestratorStart?: () => Promise<unknown>;
140	  }
141	) {
142	  (globalThis as Record<string, unknown>)['API'] = {
143	    getProject:           apiStubs.getProject           ?? (() => Promise.resolve(makeProject())),
144	    getPlanDocument:      apiStubs.getPlanDocument       ?? (() => Promise.reject({ code: 'NOT_FOUND' })),
145	    getWorkPackageOverview: apiStubs.getWorkPackageOverview ?? (() => Promise.resolve(null)),
146	    getProjectHealth:     apiStubs.getProjectHealth      ?? (() => Promise.resolve({ work_packages_needing_reset: 0 })),
147	    getRunLogs:           apiStubs.getRunLogs            ?? (() => Promise.resolve([])),
148	    orchestratorGetQueue: apiStubs.orchestratorGetQueue  ?? (() => Promise.resolve([])),
149	    getRunMetadata:       apiStubs.getRunMetadata        ?? (() => Promise.reject(new Error('not stubbed'))),
150	    orchestratorStart:    apiStubs.orchestratorStart     ?? (() => Promise.reject(new Error('not stubbed'))),
151	  };
152	
153	  globalThis.renderProjectDetail(app, slug);
154	
155	  // Poll until #orchestrator-runs-section stops showing the loading placeholder,
156	  // or until we give up (200ms). This handles the multi-level promise chain:
157	  //   Promise.all → .then() sets innerHTML → getRunLogs() → .then() updates section.
158	  const start = Date.now();
159	  while (Date.now() - start < 200) {
160	    await new Promise<void>((resolve) => setTimeout(resolve, 10));
161	    const el = app.querySelector('#orchestrator-runs-section');
162	    if (!el || !el.innerHTML.includes('Loading runs')) break;
163	  }
164	}
165	
166	// ---------------------------------------------------------------------------
167	// Tests
168	// ---------------------------------------------------------------------------
169	
170	describe('renderProjectDetail — Orchestrator Runs section', () => {
171	  let app: HTMLElement;
172	
173	  beforeEach(() => {
174	    app = document.createElement('div');
175	    document.body.appendChild(app);
176	  });
177	
178	  afterEach(() => {
179	    if (app.parentNode) app.parentNode.removeChild(app);
180	  });
181	
182	  // ── Hidden by default ─────────────────────────────────────────────────────
183	
184	  it('keeps "Orchestrator Runs" wrapper hidden when getRunLogs returns [] (vscode runner)', async () => {
185	    await renderWithAPI(app, 'my-project', {
186	      getProject: () => Promise.resolve(makeProject({ runner: 'vscode' })),
187	      getRunLogs: () => Promise.resolve([]),
188	    });
189	
190	    const wrapper = app.querySelector('#orchestrator-runs-wrapper') as HTMLElement | null;
191	    expect(wrapper).not.toBeNull();
192	    expect(wrapper!.style.display).toBe('none');
193	  });
194	
195	  it('keeps "Orchestrator Runs" wrapper hidden when runner is undefined and no logs', async () => {
196	    await renderWithAPI(app, 'my-project', {
197	      getProject: () => Promise.resolve(makeProject({})), // no runner field
198	      getRunLogs: () => Promise.resolve([]),
199	    });
200	
201	    const wrapper = app.querySelector('#orchestrator-runs-wrapper') as HTMLElement | null;
202	    expect(wrapper).not.toBeNull();
203	    expect(wrapper!.style.display).toBe('none');
204	  });
205	
206	  // ── Empty state ───────────────────────────────────────────────────────────
207	
208	  it('keeps wrapper hidden when getRunLogs returns empty array', async () => {
209	    await renderWithAPI(app, 'my-project', {
210	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
211	      getRunLogs: () => Promise.resolve([]),
212	    });
213	
214	    const wrapper = app.querySelector('#orchestrator-runs-wrapper') as HTMLElement | null;
215	    expect(wrapper).not.toBeNull();
216	    expect(wrapper!.style.display).toBe('none');
217	  });
218	
219	  // ── Populated state ───────────────────────────────────────────────────────
220	
221	  it('renders each log entry with run number, date, and working href', async () => {
222	    const logs = [
223	      { filename: '20260225T113355-my-project.jsonl', is_active: false },
224	      { filename: '20260226T080000-my-project.jsonl', is_active: false },
225	    ];
226	
227	    await renderWithAPI(app, 'my-project', {
228	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
229	      getRunLogs: () => Promise.resolve(logs),
230	    });
231	
232	    // Wrapper becomes visible when logs exist
233	    const wrapper = app.querySelector('#orchestrator-runs-wrapper') as HTMLElement | null;
234	    expect(wrapper).not.toBeNull();
235	    expect(wrapper!.style.display).toBe('');
236	
237	    // Run numbers appear
238	    expect(app.innerHTML).toContain('Run #1');
239	    expect(app.innerHTML).toContain('Run #2');
240	
241	    // Raw slug/filename not shown as visible label text
242	    const runItems = app.querySelectorAll('#orchestrator-runs-section .run-event span[style*="font-size:13px"]');
243	    runItems.forEach((el) => expect(el.textContent).not.toContain('.jsonl'));
244	
245	    // Run event styling applied
246	    expect(app.innerHTML).toContain('run-event');
247	
248	    // Links to the correct route (href still uses the full filename)
249	    expect(app.innerHTML).toContain(
250	      '#/projects/my-project/runs/' + encodeURIComponent(logs[0]!.filename)
251	    );
252	    expect(app.innerHTML).toContain(
253	      '#/projects/my-project/runs/' + encodeURIComponent(logs[1]!.filename)
254	    );
255	  });
256	
257	  it('encodes the slug in the run href', async () => {
258	    await renderWithAPI(app, 'slug/with/slashes', {
259	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
260	      getRunLogs: () => Promise.resolve([{ filename: '20260225T113355-some-project.jsonl', is_active: false }]),
261	    });
262	
263	    expect(app.innerHTML).toContain(encodeURIComponent('slug/with/slashes'));
264	  });
265	
266	  it('shows logs for non-orchestrator runner when log files exist', async () => {
267	    await renderWithAPI(app, 'my-project', {
268	      getProject: () => Promise.resolve(makeProject({ runner: 'vscode' })),
269	      getRunLogs: () => Promise.resolve([{ filename: '20260225T113355-my-project.jsonl', is_active: false }]),
270	    });
271	
272	    const wrapper = app.querySelector('#orchestrator-runs-wrapper') as HTMLElement | null;
273	    expect(wrapper).not.toBeNull();
274	    expect(wrapper!.style.display).toBe('');
275	    expect(app.innerHTML).toContain('Run #1');
276	  });
277	
278	  it('numbers runs chronologically — newest run gets the highest number', async () => {
279	    const logs = [
280	      { filename: '20260323T100000-my-project.jsonl', is_active: false }, // oldest → #1
281	      { filename: '20260325T090000-my-project.jsonl', is_active: false }, // newest → #3
282	      { filename: '20260324T120000-my-project.jsonl', is_active: false }, // middle → #2
283	    ];
284	
285	    await renderWithAPI(app, 'my-project', {
286	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
287	      getRunLogs: () => Promise.resolve(logs),
288	    });
289	
290	    const section = app.querySelector('#orchestrator-runs-section')!;
291	    const html = section.innerHTML;
292	    // Sorted descending: #3 first, then #2, then #1
293	    expect(html.indexOf('Run #3')).toBeLessThan(html.indexOf('Run #2'));
294	    expect(html.indexOf('Run #2')).toBeLessThan(html.indexOf('Run #1'));
295	    // Timestamps also appear newest-first
296	    expect(html.indexOf('20260325')).toBeLessThan(html.indexOf('20260324'));
297	    expect(html.indexOf('20260324')).toBeLessThan(html.indexOf('20260323'));

298	  });
299	
300	  it('shows a Running badge for an active run', async () => {
301	    const logs = [
302	      { filename: '20260325T120000-my-project.jsonl', is_active: true },
303	    ];
304	
305	    await renderWithAPI(app, 'my-project', {
306	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
307	      getRunLogs: () => Promise.resolve(logs),
308	    });
309	
310	    expect(app.innerHTML).toContain('Running');
311	    expect(app.innerHTML).toContain('badge-in-progress');
312	  });
313	
314	  it('does not show a Running badge for a completed run', async () => {
315	    const logs = [
316	      { filename: '20260325T120000-my-project.jsonl', is_active: false },
317	    ];
318	
319	    await renderWithAPI(app, 'my-project', {
320	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
321	      getRunLogs: () => Promise.resolve(logs),
322	    });
323	
324	    // Scope check to the runs section — the project status badge also uses badge-in-progress
325	    const section = app.querySelector('#orchestrator-runs-section');
326	    expect(section).not.toBeNull();
327	    expect(section!.innerHTML).not.toContain('badge-in-progress');
328	  });
329	
330	  it('shows a Dry Run badge for a run with is_dry_run: true', async () => {
331	    const logs = [
332	      { filename: '20260325T120000-my-project.jsonl', is_active: false, is_dry_run: true },
333	    ];
334	
335	    await renderWithAPI(app, 'my-project', {
336	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
337	      getRunLogs: () => Promise.resolve(logs),
338	    });
339	
340	    const section = app.querySelector('#orchestrator-runs-section');
341	    expect(section).not.toBeNull();
342	    expect(section!.innerHTML).toContain('Dry Run');
343	    expect(section!.innerHTML).toContain('badge-dry-run');
344	  });
345	
346	  it('does not show a Dry Run badge when is_dry_run is false', async () => {
347	    const logs = [
348	      { filename: '20260325T120000-my-project.jsonl', is_active: false, is_dry_run: false },
349	    ];
350	
351	    await renderWithAPI(app, 'my-project', {
352	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
353	      getRunLogs: () => Promise.resolve(logs),
354	    });
355	
356	    const section = app.querySelector('#orchestrator-runs-section');
357	    expect(section).not.toBeNull();
358	    expect(section!.innerHTML).not.toContain('badge-dry-run');
359	  });
360	
361	  it('shows both Running and Dry Run badges for an active dry run', async () => {
362	    const logs = [
363	      { filename: '20260325T120000-my-project.jsonl', is_active: true, is_dry_run: true },
364	    ];
365	
366	    await renderWithAPI(app, 'my-project', {
367	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
368	      getRunLogs: () => Promise.resolve(logs),
369	    });
370	
371	    const section = app.querySelector('#orchestrator-runs-section');
372	    expect(section).not.toBeNull();
373	    expect(section!.innerHTML).toContain('badge-in-progress');
374	    expect(section!.innerHTML).toContain('badge-dry-run');
375	    expect(section!.innerHTML).toContain('Running');
376	    expect(section!.innerHTML).toContain('Dry Run');
377	  });
378	
379	  it('only shows Running badge on the most-recent run even if older runs have is_active: true', async () => {
380	    // Simulates runs that were killed without writing run_end — they appear active
381	    // in the file, but only the newest one can truly be running.
382	    const logs = [
383	      { filename: '20260323T100000-my-project.jsonl', is_active: true }, // old, interrupted
384	      { filename: '20260325T090000-my-project.jsonl', is_active: true }, // newest, genuinely active
385	      { filename: '20260324T120000-my-project.jsonl', is_active: true }, // middle, interrupted
386	    ];
387	
388	    await renderWithAPI(app, 'my-project', {
389	      getProject: () => Promise.resolve(makeProject({ runner: 'orchestrator' })),
390	      getRunLogs: () => Promise.resolve(logs),
391	    });
392	
393	    const section = app.querySelector('#orchestrator-runs-section')!;
394	    const badges = section.querySelectorAll('.badge-in-progress');
