445	// ---------------------------------------------------------------------------
446	// WP-013: Queue-aware active run section
447	// ---------------------------------------------------------------------------
448	
449	describe('renderProjectDetail — WP-013: queue-aware active run (AC-1 to AC-5)', () => {
450	  let app: HTMLElement;
451	
452	  beforeEach(() => {
453	    app = document.createElement('div');
454	    document.body.appendChild(app);
455	  });
456	
457	  afterEach(() => {
458	    if (app.parentNode) app.parentNode.removeChild(app);
459	  });
460	
461	  // Shared factory for a minimal queue entry matching a given log filename.
462	  function makeQueueEntry(logFilename: string, overrides: Record<string, unknown> = {}) {
463	    return {
464	      id:              'queue-entry-1',
465	      pid:             42424,
466	      logFilename,
467	      expectedSlug:    'my-project',
468	      startedAt:       new Date(Date.now() - 30_000).toISOString(),
469	      effectiveStatus: 'started',
470	      progress:        null,
471	      lastAction:      null,
472	      ...overrides,
473	    };
474	  }
475	
476	  // Helper: wait for queue-aware rendering to settle (queue fetch = extra promise hop).
477	  async function flush(): Promise<void> {
478	    const start = Date.now();
479	    while (Date.now() - start < 300) {
480	      await new Promise<void>((resolve) => setTimeout(resolve, 15));
481	      const el = app.querySelector('#orchestrator-runs-section');
482	      if (el && !el.innerHTML.includes('Loading runs')) break;
483	    }
484	    // Extra hops for orchestratorGetQueue resolution.
485	    for (let i = 0; i < 5; i++) await Promise.resolve();
486	  }
487	
488	  // ── AC-1: Active run with matching queue entry ────────────────────────────
489	
490	  it('AC-1: calls renderStatusCard with the matching queue entry', async () => {
491	    const activeLog = { filename: '20260505T120000-my-project.jsonl', is_active: true };
492	    const queueEntry = makeQueueEntry(activeLog.filename);
